package dev.pocketengine.store;
import android.app.Application;
import dev.pocketengine.core.RunControl;
import java.lang.reflect.Method;
import java.util.UUID;
import java.util.concurrent.atomic.AtomicInteger;
import org.json.JSONArray;
import org.json.JSONObject;
import org.junit.Test;
import org.junit.runner.RunWith;
import org.robolectric.RobolectricTestRunner;
import org.robolectric.RuntimeEnvironment;
import org.robolectric.annotation.Config;
import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class)
@Config(sdk=35,manifest=Config.NONE,application=Application.class)
public final class NativeWorkflowReadTest {
 TaskStore store(){return new TaskStore(RuntimeEnvironment.getApplication());}
 JSONObject request(String occurrence,long revision)throws Exception{return new JSONObject().put("origin",new JSONObject().put("kind","automation").put("occurrenceId",occurrence)).put("ruleId","rule").put("ruleRevision",revision).put("revision",1).put("goal","owner reminder");}
 RunControl control(JSONObject t)throws Exception{RunControl c=new RunControl();c.bindHostRun(t.getString("id"),t.getString("runId"),t.getInt("coordinatorEpoch"));return c;}
 void write(TaskStore s,JSONObject t)throws Exception{Method m=TaskStore.class.getDeclaredMethod("write",JSONObject.class);m.setAccessible(true);m.invoke(s,t);}
 @Test public void originalOccurrenceLookupDoesNotUseThe200RowDisplayAndPreservesExactRuleRevision()throws Exception{TaskStore s=store();String occurrence=UUID.randomUUID().toString();JSONObject original=s.createReminderTask(request(occurrence,3000000000L),"main_screen");for(int i=0;i<205;i++)s.create("later task "+i);assertEquals(200,s.list().length());JSONObject found=s.automationTask(occurrence);assertEquals(original.getString("id"),found.getString("id"));assertEquals(3000000000L,found.getLong("ruleRevision"));assertEquals(3000000000L,found.getJSONObject("origin").getLong("ruleRevision"));assertNull(s.automationTask("absent"));}
 @Test public void duplicateOrForeignOwnerOccurrenceCannotBeSelectedAsEvidence()throws Exception{TaskStore s=store();String occurrence=UUID.randomUUID().toString();JSONObject first=s.createReminderTask(request(occurrence,3),"main_screen");JSONObject duplicate=s.create("legacy duplicate");duplicate.put("origin",first.getJSONObject("origin"));write(s,duplicate);assertThrows(SecurityException.class,()->s.automationTask(occurrence));String other=UUID.randomUUID().toString();JSONObject foreign=s.createReminderTask(request(other,3),"main_screen");foreign.put("spaceId","another");write(s,foreign);assertThrows(SecurityException.class,()->s.automationTask(other));}
 @Test public void retainedAuthorityCanCheckOriginalGrantWithoutRecursionOrCreatingAnotherOperation()throws Exception{TaskStore s=store();JSONObject t=s.startAttempt(s.createCapabilityTask("native media","").getString("id"),"capabilities",5);String id=t.getString("id"),run=t.getString("runId");int epoch=t.getInt("coordinatorEpoch");RunControl c=control(t);s.authorizeTools(id,run,new JSONArray().put("media_workflow"));AtomicInteger checks=new AtomicInteger();c.setAuthorityCheck(()->{checks.incrementAndGet();s.checkCapabilityCurrent(id,run,epoch,"media_workflow");});s.checkCapability(id,run,epoch,"media_workflow",c);String before=s.get(id,false).toString();c.check();assertEquals(before,s.get(id,false).toString());String operation=s.journal(id,run,epoch,c).beginOperation("media_workflow",new JSONObject().put("configRevision",7));c.check();assertTrue(checks.get()>1);assertEquals(1,s.get(id,false).getJSONArray("operations").length());assertEquals(id,s.operationTask("media",operation));c.pause();assertThrows(SecurityException.class,()->s.checkCapability(id,run,epoch,"media_workflow",c));c.resume();s.requestCancel(id,run);assertThrows(SecurityException.class,()->s.checkCapabilityCurrent(id,run,epoch,"media_workflow"));}
 @Test public void currentCapabilityReadRejectsOldEpochMissingToolEndedRunAndLostPhoneLease()throws Exception{TaskStore s=store();JSONObject t=s.startAttempt(s.create("phone read fence").getString("id"),"main_screen",5);String id=t.getString("id"),run=t.getString("runId");int epoch=t.getInt("coordinatorEpoch");s.authorizeTools(id,run,new JSONArray().put("media_workflow"));s.checkCapabilityCurrent(id,run,epoch,"media_workflow");assertThrows(SecurityException.class,()->s.checkCapabilityCurrent(id,run,epoch+1,"media_workflow"));assertThrows(SecurityException.class,()->s.checkCapabilityCurrent(id,run,epoch,"not_granted"));var f=TaskStore.class.getDeclaredField("db");f.setAccessible(true);((android.database.sqlite.SQLiteDatabase)f.get(s)).delete("leases","run_id=?",new String[]{run});assertThrows(SecurityException.class,()->s.checkCapabilityCurrent(id,run,epoch,"media_workflow"));s.endAttempt(id,run,"cancelled","ended",new JSONObject());assertThrows(SecurityException.class,()->s.checkCapabilityCurrent(id,run,epoch,"media_workflow"));}
 @Test public void mediaOperationLookupOnlyUsesTheExplicitOriginalMediaJournalTools()throws Exception{TaskStore s=store();for(String tool:new String[]{"media_workflow","media_generate_image","media_synthesize_speech","workspace_write"}){JSONObject t=s.startAttempt(s.createCapabilityTask("native owner action","").getString("id"),"capabilities",3);String id=t.getString("id"),run=t.getString("runId");s.authorizeTools(id,run,new JSONArray().put(tool));String op=s.journal(id,run,t.getInt("coordinatorEpoch"),control(t)).beginOperation(tool,new JSONObject());assertEquals(tool.equals("workspace_write")?null:id,s.operationTask("media",op));}assertNull(s.operationTask("media","missing"));}
}
